INSERT INTO public.stories (slug, title, title_vi, title_ko, category, content_type, status, is_featured, published_at, cover_image_url, excerpt, excerpt_vi, excerpt_ko, body_en, body_ko) VALUES ('kiss-of-the-sea-fireworks-guide', 'Kiss of the Sea Show & Nightly Fireworks: Complete Guide', 'Show Kiss of the Sea & Pháo Hoa Hàng Đêm: Cẩm Nang Chi Tiết', '키스 오브 더 씨 쇼 & 매일 밤 불꽃놀이 완벽 관람 가이드', 'Shows & Entertainment', 'guide', 'published', TRUE, '2026-10-26T00:00:00Z', '/stock/workout.webp', 'Everything you need to know about the multi-million dollar water & laser show, plus the best free and paid vantage points for the 21:30 fireworks.', 'Tất cả những điều bạn cần biết về show diễn nước và laser triệu đô cùng những vị trí ngắm pháo hoa 21:30 đẹp nhất.', '워터 스크린과 레이저, 불꽃이 어우러진 멀티미디어 쇼와 매일 밤 21시 30분 터지는 불꽃놀이 명당 총정리.', 'Sunset Town is world-renowned for its iconic sunset, but when night falls, the energy reaches its peak at the Infinity Arena, the worlds largest sea-based theater.\n\n1. Show Time: 20:30 - 21:05\n2. Fireworks: 21:15 - 21:30\n3. Best spots: Inside Arena VIP seats, on Kiss Bridge, or at Amalfi rooftop cocktail lounges.', '선셋타운은 아름다운 노을로도 유명하지만, 밤이 찾아오면 세계 최대 규모 해상 무대 인피니티 아레나에서 화려한 축제가 시작됩니다.\n\n1. 공연 시간: 20:30~21:05\n2. 불꽃놀이: 21:15~21:30 (키스 브릿지 상공)\n3. 명당: 공연장 VIP석, 키스 브릿지 위, 아말피 해안가 루프탑 바.') ON CONFLICT (slug) DO UPDATE SET title = EXCLUDED.title, body_en = EXCLUDED.body_en, body_ko = EXCLUDED.body_ko, excerpt = EXCLUDED.excerpt, is_featured = EXCLUDED.is_featured, cover_image_url = EXCLUDED.cover_image_url;
INSERT INTO public.stories (slug, title, title_vi, title_ko, category, content_type, status, is_featured, published_at, cover_image_url, excerpt, excerpt_vi, excerpt_ko, body_en, body_ko) VALUES ('hon-thom-cable-car-day-trip', 'Hon Thom Cable Car: Worlds Longest Sea Crossing Tips', 'Cáp Treo Hòn Thơm: Kinh Nghiệm Đi Tuyến Cáp Treo Vượt Biển Dài Nhất Thế Giới', '혼똔섬 케이블카 & 아쿠아토피아 워터파크 당일치기 꿀팁', 'Tours & Cable Car', 'guide', 'published', TRUE, '2026-10-26T00:00:00Z', '/stock/hero.webp', 'Essential advice for taking the 7,899m Guinness-record cable car from Sunset Town station to Sun World Hon Thom Nature Park.', 'Lời khuyên cần thiết khi trải nghiệm tuyến cáp treo 7.899m kỷ lục Guinness từ ga Ánh Dương sang Sun World Hòn Thơm.', '선셋타운 아냐즈엉역에서 출발하는 7,899m 기네스북 등재 해상 케이블카 탑승 요령 및 시간표 안내.', 'Starting from the Roman-inspired An Thoi Departure Station in Sunset Town, the Hon Thom Cable Car stretches 7,899.9 meters across the open sea.\n\nPractical Tips:\n- Check operating hours timetable before departure.\n- Tickets include Aquatopia Water Park and Exotica Theme Park.\n- Best photo time: sit on west side during 16:30 return trip for golden sunset.', '고대 로마 콜로세움을 모티브로 지어진 선셋타운 아냐즈엉(An Thoi)역에서 출발하여 바다 위를 건너 혼똔섬까지 연결됩니다.\n\n핵심 꿀팁:\n- 운행 시간표를 미리 확인하세요.\n- 왕복 티켓에 아쿠아토피아 워터파크와 롤러코스터 이용이 기본 포함됩니다.\n- 오후 16시 30분 섬에서 돌아오는 케이블카 서쪽 창가에서 황금빛 노을을 감상하세요.') ON CONFLICT (slug) DO UPDATE SET title = EXCLUDED.title, body_en = EXCLUDED.body_en, body_ko = EXCLUDED.body_ko, excerpt = EXCLUDED.excerpt, is_featured = EXCLUDED.is_featured, cover_image_url = EXCLUDED.cover_image_url;
INSERT INTO public.stories (slug, title, title_vi, title_ko, category, content_type, status, is_featured, published_at, cover_image_url, excerpt, excerpt_vi, excerpt_ko, body_en, body_ko) VALUES ('vui-fest-bazaar-night-market-food', 'VUI-Fest Bazaar: Seaside Night Market Street Food & Vibes', 'Chợ Đêm Vui Fest Bazaar: Thiên Đường Ẩm Thực Ven Biển & Âm Nhạc', '부이페스트 바자(VUI-Fest Bazaar): 바다 앞 야시장 먹거리와 버스킹', 'Night Market & Food', 'guide', 'published', FALSE, '2026-10-26T00:00:00Z', '/stock/hobby.webp', 'Explore Vietnams first creative seaside night market, featuring eco-friendly packaging, local delicacies, and live street performances.', 'Khám phá chợ đêm sáng tạo bên bờ biển đầu tiên tại Việt Nam với ẩm thực địa phương, đồ thủ công và biểu diễn nghệ thuật đường phố.', '베트남 최초의 바닷가 크리에이티브 야시장. 해산물 꼬치와 로컬 맥주, 길거리 버스킹 공연을 한자리에서 즐기는 법.', 'Open every evening along the seaside boulevard, VUI-Fest Bazaar brings together dozens of artisanal food stalls, local crafts, and impromptu circus and musical shows.\n\n- Hours: 16:00 - 24:00 Daily\n- Highlights: Grilled Phu Quoc seafood skewers, craft beer, and Loang Xoang street circus show.', '해안 산책로를 따라 매일 저녁 문을 여는 부이페스트(VUI-Fest) 바자는 개성 넘치는 푸드 트럭과 수공예품 부스, 신나는 버스킹 공연이 어우러지는 활기찬 야시장입니다.\n\n- 영업 시간: 매일 16:00 ~ 24:00\n- 대표 먹거리: 버터 갈릭 한치/오징어 구이, 베트남 전통 반미, 수제맥주, 주방 도구로 비트를 만드는 로앙쇼앙 서커스 공연.') ON CONFLICT (slug) DO UPDATE SET title = EXCLUDED.title, body_en = EXCLUDED.body_en, body_ko = EXCLUDED.body_ko, excerpt = EXCLUDED.excerpt, is_featured = EXCLUDED.is_featured, cover_image_url = EXCLUDED.cover_image_url;
